 def P(pmid,**fields):
  p=dict(c.execute('SELECT * FROM literature_papers WHERE paper_id=?',('PMID:'+pmid,)).fetchone());assert p['reading_level']=='indexed_abstract'
  a=next(a for a in ET.parse(ROOT/p['raw_path']).getroot().findall('PubmedArticle') if a.findtext('./MedlineCitation/PMID')==pmid)
  raw=[dict(label=x.get('Label',''),text=''.join(x.itertext())) for x in a.findall('./MedlineCitation/Article/Abstract/AbstractText')]
  stored=json.loads(p['abstract_json']);assert len(raw)==len(stored) and all(x['label']==y['label'] and norm(x['text'])==norm(y['text']) for x,y in zip(raw,stored))
  p=dict(paper_id=p['paper_id'],pmid=pmid,doi=p['doi'],title=p['title'],journal=p['journal'],publication_date=p['publication_date'],raw_path=p['raw_path'],source_url=p['source_url'],source_locator=f'PubmedArticle[MedlineCitation/PMID="{pmid}"]/MedlineCitation/Article/Abstract',raw_sha256=hashlib.sha256((ROOT/p['raw_path']).read_bytes()).hexdigest(),abstract_segments=raw,normalized_abstract_sha256=hashlib.sha256(norm(' '.join(x['text'] for x in raw)).encode()).hexdigest(),reading_level='abstract_only',records=[],**fields);papers.append(p);return p
