  found=[(i,s) for i,s in enumerate(p['abstract_segments'],1) if norm(quote) in norm(s['text'])];assert found,(p['paper_id'],quote)
  i,segment=found[0]
  if method_quote:assert any(norm(method_quote) in norm(s['text']) for s in p['abstract_segments']),(p['paper_id'],method_quote)
